using UnityEngine;

// Generated by AI
// Temporary test helper: lets UI buttons call HUDController.ShowFact and
// SettingsPanel.ShowCaption, because a UnityEvent button can only pass one parameter.
public class FactTester : MonoBehaviour
{
    [SerializeField] private HUDController hud;
    [SerializeField] private SettingsPanel settings;

    public void ShowSampleFact()
    {
        if (hud == null)
        {
            Debug.LogWarning("FactTester: HUDController is not assigned.");
            return;
        }
        hud.ShowFact(
            "El Florero de Llorente",
            "El 20 de julio de 1810 en Bogotá, una discusión por un florero prestado desató el inicio de la independencia.");
    }

    public void ShowSampleCaption()
    {
        if (settings == null)
        {
            Debug.LogWarning("FactTester: SettingsPanel is not assigned.");
            return;
        }
        settings.ShowCaption("[Sonido: campana de iglesia]", 3f);
    }
}